    fun tr(text: String, lang: String): String {
        if (lang == "ru" || text.isEmpty()) return text
        val idx = getLangIndex(lang)

        // 1. Direct exact match
        val direct = PHRASES[text]
        if (direct != null && idx < direct.size) return direct[idx]

        // 2. Direct trimmed match
        val trimmed = text.trim()
        val trimmedMatch = PHRASES[trimmed]
        if (trimmedMatch != null && idx < trimmedMatch.size) {
            val trVal = trimmedMatch[idx]
            return if (text.startsWith(" ") || text.endsWith(" ")) {
                val leading = text.takeWhile { it.isWhitespace() }
                val trailing = text.takeLastWhile { it.isWhitespace() }
                "$leading$trVal$trailing"
            } else trVal
        }

        // 3. Leading icon match (preserve leading single emoji/symbol)
        val iconMatch = Regex("^([\\p{So}\\p{Sk}\\u2000-\\u3300\\uD800-\\uDFFF\\s•\\-]+)(.*)$").find(trimmed)
        if (iconMatch != null) {
            val iconPrefix = iconMatch.groupValues[1]
            val rest = iconMatch.groupValues[2].trim()
            val restTr = PHRASES[rest]?.get(idx)
            if (restTr != null) {
                return "$iconPrefix$restTr"
            }
        }

        // 4. Dynamic Regex and Template rules for interpolated strings
        var res = translateDynamicTemplates(text, lang, idx)
        if (res != text) return res

        // 5. Units localization (GB, MB, KB, B, TB, MB/s)
        res = localizeUnits(res, idx)

        // 6. Substring containment search in dictionary (for compound titles/headers)
        var replaced = res
        for ((ruKey, trArr) in PHRASES) {
            if (ruKey.length >= 6 && replaced.contains(ruKey)) {
                val targetTr = trArr[idx]
                if (targetTr.isNotEmpty()) {
                    replaced = replaced.replace(ruKey, targetTr)
                }
            }
        }
        return replaced
    }

    private fun localizeUnits(text: String, idx: Int): String {
        val speedUnit = if (idx == 2) "Mo/s" else "MB/s" // French Mo/s vs MB/s
        return text
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*МБ/с\\b"""), "$1 $speedUnit")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*КБ/с\\b"""), "$1 KB/s")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*ГБ/с\\b"""), "$1 GB/s")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*ГБ\\b"""), "$1 GB")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*МБ\\b"""), "$1 MB")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*КБ\\b"""), "$1 KB")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*ТБ\\b"""), "$1 TB")
            .replace(Regex("""(?i)\\b(\\d+(?:[.,]\\d+)?)\\s*Б\\b"""), "$1 B")
    }

    private fun translateDynamicTemplates(src: String, lang: String, idx: Int): String {
        // Files in queue
        val fQueue = Regex("""(?i)^Файлов в очереди:\\s*(\\d+)""").find(src)
        if (fQueue != null) {
            val num = fQueue.groupValues[1]
            return when (lang) {
                "de" -> "Dateien in der Warteschlange: $num"
                "fr" -> "Fichiers en file d'attente: $num"
                "zh" -> "队列中的文件: $num"
                "ko" -> "대기열의 파일: $num"
                "ja" -> "キュー内のファイル: $num"
                "es" -> "Archivos en cola: $num"
                "it" -> "File in coda: $num"
                "pt" -> "Arquivos na fila: $num"
                "hi" -> "कतार में फ़ाइलें: $num"
                else -> "Files in queue: $num"
            }
        }

        // Games in queue
        val gQueue = Regex("""(?i)^Игр в очереди:\\s*(\\d+)""").find(src)
        if (gQueue != null) {
            val num = gQueue.groupValues[1]
            return when (lang) {
                "de" -> "Spiele in der Warteschlange: $num"
                "fr" -> "Jeux en file d'attente: $num"
                "zh" -> "队列中的游戏: $num"
                "ko" -> "대기열의 게임: $num"
                "ja" -> "キュー内のゲーム: $num"
                "es" -> "Juegos en cola: $num"
                "it" -> "Giochi in coda: $num"
                "pt" -> "Jogos na fila: $num"
                "hi" -> "कतार में खेल: $num"
                else -> "Games in queue: $num"
            }
        }

        // Selected: X
        val selM = Regex("""(?i)^Выбрано:\\s*(\\d+)""").find(src)
        if (selM != null) {
            val num = selM.groupValues[1]
            return when (lang) {
                "de" -> "Ausgewählt: $num"
                "fr" -> "Sélectionné: $num"
                "zh" -> "已选择: $num"
                "ko" -> "선택됨: $num"
                "ja" -> "選択済み: $num"
                "es" -> "Seleccionado: $num"
                "it" -> "Selezionato: $num"
                "pt" -> "Selecionado: $num"
                "hi" -> "चयनित: $num"
                else -> "Selected: $num"
            }
        }

        // Active tasks: X
        val aTasks = Regex("""(?i)^Активных задач:\\s*(\\d+)""").find(src)
        if (aTasks != null) {
            val num = aTasks.groupValues[1]
            return when (lang) {
                "de" -> "Aktive Aufgaben: $num"
                "fr" -> "Tâches actives: $num"
                "zh" -> "活动任务: $num"
                "ko" -> "활성 작업: $num"
                "ja" -> "アクティブなタスク: $num"
                "es" -> "Tareas activas: $num"
                "it" -> "Attività attive: $num"
                "pt" -> "Tarefas ativas: $num"
                "hi" -> "सक्रिय कार्य: $num"
                else -> "Active tasks: $num"
            }
        }

        // Done: X
        val doneM = Regex("""(?i)^Готово:\\s*(.+)""").find(src)
        if (doneM != null) {
            val rest = doneM.groupValues[1]
            return when (lang) {
                "de" -> "Fertig: $rest"
                "fr" -> "Terminé: $rest"
                "zh" -> "完成: $rest"
                "ko" -> "완료: $rest"
                "ja" -> "完了: $rest"
                "es" -> "Listo: $rest"
                "it" -> "Fatto: $rest"
                "pt" -> "Concluído: $rest"
                "hi" -> "पूर्ण: $rest"
                else -> "Done: $rest"
            }
        }

        // Error: X
        val errM = Regex("""(?i)^(❌\\s*)?Ошибка:\\s*(.+)""").find(src)
        if (errM != null) {
            val icon = errM.groupValues[1]
            val rest = errM.groupValues[2]
            return when (lang) {
                "de" -> "${icon}Fehler: $rest"
                "fr" -> "${icon}Erreur: $rest"
                "zh" -> "${icon}错误: $rest"
                "ko" -> "${icon}오류: $rest"
                "ja" -> "${icon}エラー: $rest"
                "es" -> "${icon}Error: $rest"
                "it" -> "${icon}Errore: $rest"
                "pt" -> "${icon}Erro: $rest"
                "hi" -> "${icon}त्रुटि: $rest"
                else -> "${icon}Error: $rest"
            }
        }

        // Ready for processing (Games in queue: X, files: Y)
        val readyM = Regex("""(?i)^Готов к обработке\\s*\\(Игр в очереди:\\s*(\\d+),\\s*файлов:\\s*(\\d+)\\)""").find(src)
        if (readyM != null) {
            val g = readyM.groupValues[1]
            val f = readyM.groupValues[2]
            return when (lang) {
                "de" -> "Bereit zur Verarbeitung (Spiele in der Warteschlange: $g, Dateien: $f)"
                "fr" -> "Prêt pour le traitement (Jeux en file: $g, fichiers: $f)"
                "zh" -> "准备处理 (队列中的游戏: $g, 文件: $f)"
                "ko" -> "처리 준비 완료 (대기열 게임: $g, 파일: $f)"
                "ja" -> "処理準備完了 (キュー内のゲーム: $g, ファイル: $f)"
                "es" -> "Listo para procesar (Juegos en cola: $g, archivos: $f)"
                "it" -> "Pronto per l'elaborazione (Giochi in coda: $g, file: $f)"
                "pt" -> "Pronto para processar (Jogos na fila: $g, arquivos: $f)"
                "hi" -> "प्रसंस्करण के लिए तैयार (कतार में खेल: $g, फ़ाइलें: $f)"
                else -> "Ready for processing (Games in queue: $g, files: $f)"
            }
        }

        // Added files to queue: X
        val addM = Regex("""(?i)^(?:В очередь добавлено|Добавлено в очередь файлов:|Добавлено файлов в очередь:)\\s*(\\d+)(.*)""").find(src)
        if (addM != null) {
            val num = addM.groupValues[1]
            return when (lang) {
                "de" -> "Dateien zur Warteschlange hinzugefügt: $num"
                "fr" -> "Fichiers ajoutés à la file d'attente: $num"
                "zh" -> "添加到队列的文件: $num"
                "ko" -> "대기열에 추가된 파일: $num"
                "ja" -> "キューに追加されたファイル: $num"
                "es" -> "Archivos añadidos a la cola: $num"
                "it" -> "File aggiunti alla coda: $num"
                "pt" -> "Arquivos adicionados à fila: $num"
                "hi" -> "कतार में जोड़ी गई फ़ाइलें: $num"
                else -> "Files added to queue: $num"
            }
        }

        // Verifying integrity and SHA-256
        val verM = Regex("""(?i)^⏳\\s*Проверка целостности и SHA-256\\s*(.+)""").find(src)
        if (verM != null) {
            val target = verM.groupValues[1]
            return when (lang) {
                "de" -> "⏳ Integrität und SHA-256 überprüfen $target"
                "fr" -> "⏳ Vérification de l'intégrité et SHA-256 $target"
                "zh" -> "⏳ 验证完整性与 SHA-256 $target"
                "ko" -> "⏳ 무결성 및 SHA-256 확인 $target"
                "ja" -> "⏳ 整合性とSHA-256の確認 $target"
                "es" -> "⏳ Verificando integridad y SHA-256 $target"
                "it" -> "⏳ Verifica integrità e SHA-256 $target"
                "pt" -> "⏳ Verificando integridade e SHA-256 $target"
                "hi" -> "⏳ अखंडता और SHA-256 की पुष्टि $target"
                else -> "⏳ Verifying integrity and SHA-256 $target"
            }
        }

        return src
    }

    fun localizeViewTree(view: View, lang: String) {
        when (view) {
            is TextView -> {
                var data = viewOrigMap[view]
                if (data == null) {
                    data = OrigViewData()
                    viewOrigMap[view] = data
                }

                // Text
                val currentText = view.text?.toString() ?: ""
                val origText = data.text ?: currentText
                if (data.text == null && currentText.isNotEmpty()) {
                    data.text = currentText
                }
                if (origText.isNotEmpty()) {
                    val translated = tr(origText, lang)
                    if (translated != currentText) {
                        view.text = translated
                    }
                }

                // Hint
                val currentHint = view.hint?.toString() ?: ""
                val origHint = data.hint ?: currentHint
                if (data.hint == null && currentHint.isNotEmpty()) {
                    data.hint = currentHint
                }
                if (origHint.isNotEmpty()) {
                    val translatedHint = tr(origHint, lang)
                    if (translatedHint != currentHint) {
                        view.hint = translatedHint
                    }
                }

                // Content description
                val currentDesc = view.contentDescription?.toString() ?: ""
                val origDesc = data.desc ?: currentDesc
                if (data.desc == null && currentDesc.isNotEmpty()) {
                    data.desc = currentDesc
                }
                if (origDesc.isNotEmpty()) {
                    val translatedDesc = tr(origDesc, lang)
                    if (translatedDesc != currentDesc) {
                        view.contentDescription = translatedDesc
                    }
                }
            }
        }

        if (view is ViewGroup) {
            for (i in 0 until view.childCount) {
                localizeViewTree(view.getChildAt(i), lang)
            }
        }
    }
}
